  Ltac dkrun1 HRT HAT HDT HFT HHT HQP HMI fuel stops dirs :=
    lazymatch goal with
    | |- evt asegs ?Q (MS ?R ?F (Z_to_bv 64 ?pc) ?fc None ?m ?ro) =>
      lazymatch type of HAT with ftbl _ _ _ ?AT =>
      lazymatch type of HDT with ftbl _ _ _ ?DT =>
